.room-capacity { position: relative; display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 6px; padding: 6px 12px; }
.room-capacity__opt { min-height: 32px; padding: 4px 10px; border: 1px solid #5d6865; color: #eef0ef; background: #202927; font: inherit; cursor: pointer; }
.room-capacity__opt[aria-pressed="true"] { color: #5df0c6; border-color: currentColor; }
.room-capacity__opt:disabled { opacity: .5; cursor: default; }
@media (max-width: 800px) {
  .rs-seats.seats--expanded, .rs-seats.seats--dense { grid-template-columns: repeat(4, minmax(125px, 1fr)); }
