    else if (phase === PHASE.PREP) this.maybeEndPrep();
  }

  dispose() {
    if (this.disposed) return;
    this.disposed = true;
    this.externalAI?.close();
    if (this.runner) { try { this.runner.stop(); } catch { /* ignore */ } }
