      this._testAudit(ps, cmd, { rejected: true }, ERR.SPECTATOR);
      return fail(ERR.SPECTATOR);
    }
    if (ps.playerId !== this.hostId) {
      this._testAudit(ps, cmd, { rejected: true }, ERR.NOT_HOST);
      return fail(ERR.NOT_HOST);
    }
