    if ('error' in parsed) {
      this._testAudit(ps, cmd, { rejected: true }, parsed.error);
      return fail(parsed.error === 'BAD_TARGET' ? ERR.BAD_TARGET : ERR.BAD_MSG);
    }
    let res;
    this._testApplying = true;
    try {
      res = this._applyTest(ps, cmd, parsed.args);
    } catch (e) {
