  }

  _testRateAllows(cmd) {
    const now = this.sched.now();
    const list = (this._testRate.get(cmd) || []).filter((t) => now >= t && now - t < TEST_RATE_WINDOW_MS);
    this._testRate.set(cmd, list);
    return list.length < TEST_RATE_COUNT;
