      cmd: String(cmd || '').slice(0, 16),
      args,
      at: this.sched.now(),
      ok,
    };
    if (code) entry.code = String(code).slice(0, 32);
    if (typeof detail === 'string' && detail) entry.detail = detail.slice(0, 120);
