    const see = p => {
      if (!p) return;
      if (p.kind === 'item' && this.gd.baseIdOf(p.id) === base) count += this.need(p.id);
      for (const item of p.items || []) if (this.gd.baseIdOf(item.id) === base) count += this.need(item.id);
