  repay(id, copies) {
    const n = Math.floor(Number(copies));
    const base = this.gd.baseIdOf(id);
    const cur = this.debt.get(base) || 0;
    if (!(n > 0) || cur <= 0) return 0;
    const k = Math.min(cur, n);
    if (cur === k) this.debt.delete(base);
    else this.debt.set(base, cur - k);
    return k;
  }
