  // server run the candidates itself. `choice` stops at 7 because a match rehearses at most 8 candidates.
  'b.rehearsalResult': {
    taskId: isId, choice: (v) => v === undefined || isInt(v, 0, 7), error: (v) => v === undefined || v === true,
    $optional: ['choice', 'error'],
