function memStorage() {
  const m = new Map();
  return {
    getItem: (k) => (m.has(k) ? m.get(k) : null),
    setItem: (k, v) => { m.set(k, String(v)); },
    removeItem: (k) => { m.delete(k); },
    /** sessionStorage is copied when a tab is duplicated */
    clone() { const c = memStorage(); for (const [k, v] of m) c.setItem(k, v); return c; },
  };
}

/** In-memory BroadcastChannel hub: messages reach every other open member asynchronously. */
function channelHub() {
  const members = new Set();
  return {
    create() {
      const ch = {
        listeners: new Set(),
        postMessage(data) {
          if (!members.has(ch)) throw new Error('InvalidStateError: channel closed');
          const copy = structuredClone(data);
          for (const m of members) {
            if (m === ch) continue;
            queueMicrotask(() => { if (members.has(m)) for (const fn of m.listeners) fn({ data: copy }); });
          }
        },
        addEventListener(type, fn) { if (type === 'message') ch.listeners.add(fn); },
        close() { members.delete(ch); },
      };
      members.add(ch);
      return ch;
    },
  };
}

describe('identity (reconnect-token selection across tabs)', () => {
  const recent = (local) => JSON.parse(local.getItem('sp.tokens') || '[]');

  test('new tab, second tab, duplicated tab, reload, reopen', async () => {
    const { createIdentity } = await mod('net.js');
    const hub = channelHub();
    const local = memStorage();
    const tab = (id, session = memStorage()) => {
      const channel = hub.create();
      return { id: createIdentity({ local, session, tabId: id, channel, queryMs: 5 }), session, channel };
    };

    const A = tab('A');
    assert.equal(await A.id.init(), null, 'fresh browser: no token → new session');
    assert.equal(A.id.getToken(), null);
    A.id.saveToken('tokA');
    assert.equal(A.id.getToken(), 'tokA');
    assert.deepEqual(recent(local), ['tokA']);

    const B = tab('B');
    assert.equal(await B.id.init(), null, 'A is live: a second tab must not take tokA');
    B.id.saveToken('tokB');
    assert.deepEqual(recent(local), ['tokB', 'tokA']);

    const dup = tab('Adup', A.session.clone());
    assert.equal(dup.session.getItem('sp.token'), 'tokA', 'duplicated tab starts with a copy of A\'s token');
    assert.equal(await dup.id.init(), null, 'duplicated tab becomes a new player');
    assert.equal(dup.session.getItem('sp.token'), null, 'copied token dropped from the duplicate');
    assert.equal(A.id.getToken(), 'tokA', 'original tab keeps its session');
    dup.channel.close();

    A.channel.close(); // A reloads: the old document is gone before the new one asks
    const A2 = tab('A2', A.session);
    assert.equal(await A2.id.init(), 'tokA', 'reload resumes the own token');
    A2.channel.close(); // tab closed

    const C = tab('C');
    assert.equal(await C.id.init(), 'tokA', 'reopened tab resumes the most recent token no live tab holds (tokB is B\'s)');
    assert.equal(C.session.getItem('sp.token'), 'tokA');
  });

  test('a busy background tab still answers (no timer-based liveness)', async () => {
    const { createIdentity } = await mod('net.js');
    const hub = channelHub();
    const local = memStorage();
    const bg = createIdentity({ local, session: memStorage(), tabId: 'bg', channel: hub.create(), queryMs: 5 });
    await bg.init();
    bg.saveToken('tokBg');
    await new Promise((r) => setTimeout(r, 30)); // arbitrary idle time: nothing to refresh
    const fresh = createIdentity({ local, session: memStorage(), tabId: 'fresh', channel: hub.create(), queryMs: 5 });
    assert.equal(await fresh.init(), null);
  });

  test('simultaneous resolution: the smaller tab id wins a shared token', async () => {
    const { createIdentity } = await mod('net.js');
    const hub = channelHub();
    const local = memStorage();
    local.setItem('sp.tokens', JSON.stringify(['tokShared']));
    const x = createIdentity({ local, session: memStorage(), tabId: 'a-tab', channel: hub.create(), queryMs: 5 });
    const y = createIdentity({ local, session: memStorage(), tabId: 'b-tab', channel: hub.create(), queryMs: 5 });
    const [tx, ty] = await Promise.all([x.init(), y.init()]);
    assert.equal(tx, 'tokShared');
    assert.equal(ty, null);
  });

  for (const [firstId, secondId, expected] of [
    ['a-tab', 'b-tab', ['tokShared', null]],
    ['b-tab', 'a-tab', [null, 'tokShared']],
  ]) {
    test(`staggered channels: ${firstId} starts before ${secondId}`, async () => {
      const { createIdentity, CLAIM_QUERY_MS } = await mod('net.js');
      const hub = channelHub(), timers = fakeTimers(), local = memStorage();
      local.setItem('sp.tokens', JSON.stringify(['tokShared']));
      const firstSession = memStorage(), secondSession = memStorage();
      const first = createIdentity({ local, session: firstSession, tabId: firstId,
        channel: hub.create(), setTimeout: timers.setTimeout });
      const firstPick = first.init();
      timers.advance(30);
      // This channel did not exist when the first tab broadcast its query.
      const second = createIdentity({ local, session: secondSession, tabId: secondId,
        channel: hub.create(), setTimeout: timers.setTimeout });
      const secondPick = second.init();
      await new Promise((r) => setImmediate(r));
      timers.advance(CLAIM_QUERY_MS - 30);
      assert.equal(await firstPick, expected[0]);
      timers.advance(30);
      assert.equal(await secondPick, expected[1]);
      assert.deepEqual([first.getToken(), second.getToken()], expected);
      assert.deepEqual([firstSession.getItem('sp.token'), secondSession.getItem('sp.token')], expected);
    });
  }

  test('staggered elections reserve fallback candidates while a live owner keeps its token', async () => {
    const { createIdentity, CLAIM_QUERY_MS } = await mod('net.js');
    const hub = channelHub(), timers = fakeTimers(), local = memStorage();
    const owner = createIdentity({ local, session: memStorage(), tabId: 'z-owner', channel: hub.create() });
    await owner.init();
    owner.saveToken('tokOwned');
    local.setItem('sp.tokens', JSON.stringify(['tokOwned', 'tokFree']));
    const first = createIdentity({ local, session: memStorage(), tabId: 'a-tab',
      channel: hub.create(), setTimeout: timers.setTimeout });
    const firstPick = first.init();
    timers.advance(30);
    const duplicateSession = memStorage();
    duplicateSession.setItem('sp.token', 'tokOwned');
    const second = createIdentity({ local, session: duplicateSession, tabId: 'b-tab',
      channel: hub.create(), setTimeout: timers.setTimeout });
    const secondPick = second.init();
    await new Promise((r) => setImmediate(r));
    timers.advance(CLAIM_QUERY_MS - 30);
    assert.equal(await firstPick, 'tokFree');
    timers.advance(30);
    assert.equal(await secondPick, null);
    assert.equal(duplicateSession.getItem('sp.token'), null, 'the copied live token is discarded');
    assert.equal(owner.getToken(), 'tokOwned', 'a live owner outranks even a smaller tab id');
  });

  test('without BroadcastChannel only the own token is used; init is idempotent; welcome during init wins', async () => {
    const { createIdentity } = await mod('net.js');
    const local = memStorage();
    local.setItem('sp.tokens', JSON.stringify(['someoneElse']));
    const lone = createIdentity({ local, session: memStorage(), tabId: 'L', channel: null });
    assert.equal(await lone.init(), null, 'never adopts a shared token it cannot verify');
    const session = memStorage();
    session.setItem('sp.token', 'mine');
    const own = createIdentity({ local, session, tabId: 'O', channel: null });
    assert.equal(own.getToken(), 'mine', 'before init: own token');
    const p1 = own.init();
    assert.equal(own.init(), p1, 'same promise');
    assert.equal(await p1, 'mine');

    const hub = channelHub();
    const racing = createIdentity({ local: memStorage(), session: memStorage(), tabId: 'R', channel: hub.create(), queryMs: 5 });
    racing.saveToken('fromWelcome'); // a welcome arrived before init finished
    assert.equal(await racing.init(), 'fromWelcome');
  });

  test('entered flag, name, clearToken, bad tokens and missing storage', async () => {
    const { createIdentity, tokenHash } = await mod('net.js');
    const local = memStorage();
    const id = createIdentity({ local, session: memStorage(), tabId: 'X', channel: null });
    await id.init();
    assert.equal(id.wasEntered(), false);
    id.setEntered(true);
    assert.equal(id.wasEntered(), true);
    id.setEntered(false);
    assert.equal(id.wasEntered(), false);
    id.saveName('凯尔希');
    assert.equal(id.loadName(), '凯尔希');
    id.saveToken('t');
    assert.deepEqual(recent(local), ['t']);
    id.clearToken();
    assert.equal(id.getToken(), null);
    assert.deepEqual(recent(local), [], 'forgotten token leaves the recent list');
    id.saveToken('');
    id.saveToken('x'.repeat(65));
    assert.equal(id.getToken(), null, 'invalid tokens ignored');
    for (let i = 0; i < 9; i++) id.saveToken(`t${i}`);
    assert.equal(recent(local).length, 4, 'recent list capped');
    local.setItem('sp.tokens', '{broken');
    id.saveToken('ok');
    assert.deepEqual(recent(local), ['ok'], 'corrupt list replaced');
    assert.match(tokenHash('abc'), /^[0-9a-f]{8}$/);
    assert.notEqual(tokenHash('abc'), tokenHash('abd'));

    const none = createIdentity({ local: null, session: null, channel: null });
    assert.equal(await none.init(), null);
    none.saveToken('x');
    assert.equal(none.getToken(), 'x', 'kept in memory for this page');
    assert.equal(none.loadName(), '');
    assert.equal(none.wasEntered(), false);
  });
});

