function fakeFetch(files) {
  const calls = [];
  const fn = async (url) => {
    calls.push(url);
    const name = url.split('/').pop();
    if (!(name in files)) return { ok: false, status: 404, json: async () => ({}) };
    const v = files[name];
    return { ok: true, status: 200, json: async () => (typeof v === 'string' ? JSON.parse(v) : v) };
  };
  fn.calls = calls;
  return fn;
}

describe('data.js', () => {
  test('indexes map, array and wrapped shapes; tolerates missing/bad files', async () => {
    const { createDataStore } = await mod('data.js');
    const fetch = fakeFetch({
      'chess.json': { chess_a: { name: 'A' }, chess_b: { name: 'B' } },
      'bonds.json': [{ bondId: 'yanShip', name: '炎' }, { bondId: 'sargonShip', name: '萨尔贡' }, { junk: 1 }],
      'items.json': { version: 2, items: [{ id: 'it1', name: 'I' }] },
      'bands.json': '{"broken": ',
    });
    const d = createDataStore({ fetch, base: '/data/' });
    const w = console.warn;
    const warns = [];
    console.warn = (m) => warns.push(m);
    try {
      const [chess] = await Promise.all([d.load('chess'), d.load('chess')]);
      assert.equal(fetch.calls.filter((u) => u === '/data/chess.json').length, 1, 'single fetch for concurrent loads');
      assert.equal(chess.chess_a.name, 'A');
      assert.equal(d.lookup('chess', 'chess_b').name, 'B');
      await d.loadAll('bonds', 'items', 'bands', 'enemies');
      assert.equal(d.lookup('bonds', 'yanShip').name, '炎');
      assert.equal(d.list('bonds').length, 2);
      assert.equal(d.lookup('items', 'it1').name, 'I');
      assert.equal(d.get('bands'), null);
      assert.equal(d.status('bands'), 'missing');
      assert.equal(d.status('enemies'), 'missing');
      assert.equal(d.lookup('enemies', 'x'), null);
      assert.equal(d.status('never'), 'idle');
      assert.equal(await d.load('../etc/passwd'), null, 'unsafe names rejected');
      await d.load('enemies');
      assert.equal(warns.filter((m) => String(m).includes('enemies')).length, 1, 'missing file warned once');
    } finally { console.warn = w; }
  });

  test('subscribe + invalidate refetches', async () => {
    const { createDataStore } = await mod('data.js');
    const fetch = fakeFetch({ 'config.json': { modes: { mode_multi_hard: { name: '绝境模拟' } } } });
    const d = createDataStore({ fetch });
    const seen = [];
    d.subscribe((n) => seen.push(n));
    await d.load('config');
    d.invalidate('config');
    await d.load('config');
    assert.equal(fetch.calls.length, 2);
    assert.deepEqual(seen, ['config', 'config', 'config']);
  });

  test('invalidate during an in-flight load: the stale load stays silent, the refetch wins', async () => {
    const { createDataStore } = await mod('data.js');
    let n = 0;
    const releases = [];
    const fetch = (url) => new Promise((resolve) => {
      const v = ++n;
      releases.push(() => resolve({ ok: true, status: 200, json: async () => ({ rec: { v } }) }));
    });
    const d = createDataStore({ fetch });
    const seen = [];
    d.subscribe((name) => seen.push(`${name}:${d.status(name)}`));
    const first = d.load('bonds');
    const second = d.invalidate('bonds');
    releases[1]();
    await second;
    releases[0]();
    await first;
    assert.equal(d.lookup('bonds', 'rec').v, 2, 'refetched value kept');
    assert.equal(d.status('bonds'), 'ready');
    assert.deepEqual(seen, ['bonds:loading', 'bonds:ready'], 'no notification from the superseded load');
    assert.equal(await d.invalidate('never-loaded'), null);
  });

  test('buildIndex edge cases', async () => {
    const { buildIndex } = await mod('data.js');
    assert.equal(buildIndex('x', null).size, 0);
    assert.equal(buildIndex('x', 42).size, 0);
    assert.equal(buildIndex('x', [{ id: 1 }, { id: 1 }, null]).size, 1);
    assert.equal(buildIndex('x', { a: 1, b: { v: 1 } }).size, 1, 'non-object values skipped');
  });
});

