// test/client-static.test.js — static and unit checks for the browser shell (public/).
//
// Static:
//   * shared/constants.js + shared/protocol.js import cleanly in Node (pure ESM, no Node APIs needed).
//   * every public/js/**/*.js and public/studio/**/*.js file (and every inline <script type="module"> in public HTML)
//     parses as an ES module (`node --input-type=module --check`, stdin).
//   * public/index.html, public/dev/uikit.html and public/studio/index.html (the plugin studio's page) only reference files
//     that exist (src/href/import map);
//     /fonts/ and /assets/ are produced by the assets pipeline and are reported, not failed, when absent.
//   * the static import graph resolves: relative/absolute specifiers point at existing files (with browser
//     URL semantics: '../../shared/x.js' from /js/ is /shared/x.js), bare specifiers are in the import map,
//     and every named import is actually exported by its target.
// Unit (pure logic of the client modules, imported directly in Node — 'preact'/'htm' resolve from
// node_modules): store, net (fake WebSocket + fake timers), identity (fake BroadcastChannel hub), data,
// screen helpers, toasts.

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PUBLIC = path.join(ROOT, 'public');
const HTML_PAGES = ['index.html', 'dev/uikit.html', 'studio/index.html'];
const OPTIONAL_PREFIXES = ['/fonts/', '/assets/']; // generated by tools/fetch-assets.mjs

// ---- helpers -------------------------------------------------------------------------------------------

function walk(dir, ext, out = []) {
  for (const name of readdirSync(dir)) {
    const p = path.join(dir, name);
    if (statSync(p).isDirectory()) walk(p, ext, out);
    else if (p.endsWith(ext)) out.push(p);
  }
  return out;
}

/** URL path served by the server → file on disk (mirrors the server/http/static.js mounts). */
function urlPathToFile(urlPath) {
  const clean = decodeURIComponent(urlPath.split(/[?#]/)[0]);
  if (clean.startsWith('/shared/')) return path.join(ROOT, clean);
  if (clean.startsWith('/data/')) return path.join(ROOT, clean);
  return path.join(PUBLIC, clean);
}

/** File under public/ → its URL path. */
const fileToUrlPath = (file) => '/' + path.relative(PUBLIC, file).split(path.sep).join('/');

function checkModuleSyntax(source) {
  const r = spawnSync(process.execPath, ['--input-type=module', '--check'], { input: source, encoding: 'utf8' });
  return r.status === 0 ? null : (r.stderr || r.stdout || 'syntax error').split('\n').slice(0, 6).join('\n');
}

function parseImportMap(htmlSrc) {
  const m = htmlSrc.match(/<script\s+type="importmap"\s*>([\s\S]*?)<\/script>/);
  return m ? JSON.parse(m[1]).imports || {} : {};
}

function inlineModules(htmlSrc) {
  const out = [];
  const re = /<script\s+type="module"\s*>([\s\S]*?)<\/script>/g;
  let m;
  while ((m = re.exec(htmlSrc))) out.push(m[1]);
  return out;
}

function htmlRefs(htmlSrc) {
  const refs = [];
  const re = /\s(?:src|href)="([^"]+)"/g;
  let m;
  while ((m = re.exec(htmlSrc))) {
    const v = m[1];
    if (/^(https?:|data:|mailto:|#|javascript:)/.test(v)) continue;
    refs.push(v);
  }
  return refs;
}

/** Static import/export-from statements: [{ spec, clause }]. Statements start at the beginning of a line. */
function staticImports(src) {
  const out = [];
  const re = /^[ \t]*(?:import|export)\b([^;'"]*?)\bfrom\s*['"]([^'"]+)['"]|^[ \t]*import\s*['"]([^'"]+)['"]/gm;
  let m;
  while ((m = re.exec(src))) {
    if (m[3]) out.push({ spec: m[3], clause: '' });
    else out.push({ spec: m[2], clause: m[1].trim() });
  }
  return out;
}

/** Names a module exports ('*' when it re-exports everything and names can't be listed). */
function exportedNames(src) {
  const names = new Set();
  let m;
  const decl = /export\s+(?:async\s+)?(?:function\s*\*?|const|let|var|class)\s+([\w$]+)/g;
  while ((m = decl.exec(src))) names.add(m[1]);
  const list = /export\s*\{([^}]*)\}/g;
  while ((m = list.exec(src))) {
    for (const part of m[1].split(',')) {
      const p = part.trim();
      if (!p) continue;
      const as = p.split(/\s+as\s+/);
      names.add((as[1] || as[0]).trim());
    }
  }
  if (/export\s+default\b/.test(src)) names.add('default');
  if (/export\s*\*\s*from/.test(src)) names.add('*');
  return names;
}

/** Imported binding names from an import clause ('default' for a default import). */
function importedNames(clause) {
  if (!clause || /^\*\s*as\s/.test(clause)) return [];
  const names = [];
  const brace = clause.match(/\{([^}]*)\}/);
  if (brace) {
    for (const part of brace[1].split(',')) {
      const p = part.trim();
      if (p) names.push(p.split(/\s+as\s+/)[0].trim());
    }
  }
  const head = clause.replace(/\{[^}]*\}/, '').replace(/,/g, ' ').trim();
  if (head && !head.startsWith('*') && /^[\w$]+$/.test(head)) names.push('default');
  return names;
}

// ---- static checks --------------------------------------------------------------------------------------

describe('shared modules', () => {
  test('constants.js and protocol.js import in Node', async () => {
    const c = await import(pathToFileURL(path.join(ROOT, 'shared/constants.js')).href);
    const p = await import(pathToFileURL(path.join(ROOT, 'shared/protocol.js')).href);
    assert.equal(typeof c.PROTOCOL_VERSION, 'number');
    for (const d of c.DIFFICULTIES) {
      assert.ok(c.DIFFICULTY_NAMES[d], `name for ${d}`);
      assert.match(c.DIFFICULTY_COLORS[d], /^#[0-9a-f]{6}$/i);
    }
    for (const code of Object.keys(c.ERR)) assert.ok(c.ERR_TEXT[code], `ERR_TEXT.${code}`);
    for (const ph of Object.keys(c.PHASE)) assert.ok(c.PHASE_NAMES[ph], `PHASE_NAMES.${ph}`);
    assert.equal(typeof p.validateC2S, 'function');
    assert.equal(p.validateC2S({ t: 'room.create', mode: 'coop', difficulty: 'HARD' }), null);
    assert.ok(Array.isArray(p.S2C) && p.S2C.includes('room.state'));
  });
});

const JS_FILES = [...walk(path.join(PUBLIC, 'js'), '.js'), ...walk(path.join(PUBLIC, 'studio'), '.js')];

describe('client modules parse as ES modules', () => {
  test('found client modules', () => {
    for (const f of ['main.js', 'net.js', 'store.js', 'data.js', 'ui/components.js', 'ui/toasts.js',
      'screens/title.js', 'screens/lobby.js', 'screens/room.js', 'screens/game.js']) {
      assert.ok(existsSync(path.join(PUBLIC, 'js', f)), `public/js/${f} exists`);
    }
  });
  for (const file of JS_FILES) {
    test(path.relative(ROOT, file), () => {
      const err = checkModuleSyntax(readFileSync(file, 'utf8'));
      assert.equal(err, null, err || '');
    });
  }
  for (const page of HTML_PAGES) {
    test(`inline modules of public/${page}`, () => {
      const src = readFileSync(path.join(PUBLIC, page), 'utf8');
      for (const mod of inlineModules(src)) {
        const err = checkModuleSyntax(mod);
        assert.equal(err, null, err || '');
      }
    });
  }
});

describe('HTML pages reference existing files', () => {
  for (const page of HTML_PAGES) {
    test(`public/${page}`, (t) => {
      const src = readFileSync(path.join(PUBLIC, page), 'utf8');
      const pageUrl = new URL(`http://host/${page}`);
      const imports = parseImportMap(src);
      assert.ok(imports.preact && imports['preact/hooks'] && imports.htm, 'import map has preact, preact/hooks, htm');
      const refs = [...htmlRefs(src), ...Object.values(imports)];
      for (const ref of refs) {
        const urlPath = new URL(ref, pageUrl).pathname;
        const file = urlPathToFile(urlPath);
        if (!existsSync(file)) {
          if (OPTIONAL_PREFIXES.some((p) => urlPath.startsWith(p))) t.diagnostic(`optional asset missing: ${urlPath}`);
          else assert.fail(`${page} references missing ${urlPath}`);
        }
      }
    });
  }
  test('index.html boots main.js as a module and has the rotate hint', () => {
    const src = readFileSync(path.join(PUBLIC, 'index.html'), 'utf8');
    assert.match(src, /<script type="module" src="\/js\/main\.js"[^>]*><\/script>/);
    assert.match(src, /class="rotate-hint"/);
    assert.match(src, /fonts\.googleapis\.com\/css2\?family=Noto\+Sans\+SC/);
    assert.match(src, /href="\/fonts\/fonts\.css"/);
  });
});

describe('static import graph resolves', () => {
  const importMap = parseImportMap(readFileSync(path.join(PUBLIC, 'index.html'), 'utf8'));
  const exportsCache = new Map();
  const exportsOf = (file) => {
    if (!exportsCache.has(file)) exportsCache.set(file, exportedNames(readFileSync(file, 'utf8')));
    return exportsCache.get(file);
  };

  function checkSource(label, src, baseUrl) {
    for (const { spec, clause } of staticImports(src)) {
      let urlPath;
      if (/^(\.{1,2}\/|\/)/.test(spec)) urlPath = new URL(spec, baseUrl).pathname;
      else {
        assert.ok(importMap[spec], `${label}: bare specifier '${spec}' is not in the import map`);
        urlPath = importMap[spec];
      }
      const file = urlPathToFile(urlPath);
      assert.ok(existsSync(file), `${label}: '${spec}' → ${urlPath} does not exist`);
      const names = exportsOf(file);
      if (names.has('*')) continue;
      for (const n of importedNames(clause)) {
        assert.ok(names.has(n), `${label}: '${n}' is not exported by ${urlPath}`);
      }
    }
  }

  for (const file of JS_FILES) {
    test(path.relative(ROOT, file), () => {
      checkSource(path.relative(ROOT, file), readFileSync(file, 'utf8'), new URL(`http://host${fileToUrlPath(file)}`));
    });
  }
  test('dev/uikit.html inline module', () => {
    const src = readFileSync(path.join(PUBLIC, 'dev/uikit.html'), 'utf8');
    for (const mod of inlineModules(src)) checkSource('uikit.html', mod, new URL('http://host/dev/uikit.html'));
  });
  test('client modules never import Node built-ins', () => {
    for (const file of JS_FILES) {
      const src = readFileSync(file, 'utf8');
      assert.doesNotMatch(src, /from\s+['"]node:/, `${path.relative(ROOT, file)} imports a node: module`);
    }
  });
});

// ---- unit: store ------------------------------------------------------------------------------------------

const mod = (rel) => import(pathToFileURL(path.join(PUBLIC, 'js', rel)).href);

describe('store.js', () => {
  test('createStore get/set/patch/subscribe', async () => {
    const { createStore } = await mod('store.js');
    const s = createStore({ a: 1, nested: { x: 1, y: 2 } });
    const seen = [];
    const off = s.subscribe((st, prev) => seen.push([st.a, prev.a]));
    s.set({ a: 2 });
    s.set((st) => ({ a: st.a + 1 }));
    s.patch('nested', { y: 5 });
    assert.deepEqual(s.get().nested, { x: 1, y: 5 });
    s.set(null); // ignored
    off();
    s.set({ a: 99 });
    assert.deepEqual(seen, [[2, 1], [3, 2], [3, 3]]);
    s.reset();
    assert.equal(s.get().a, 1);
  });

  test('a throwing listener does not break others', async () => {
    const { createStore } = await mod('store.js');
    const s = createStore({ v: 0 });
    let ok = 0;
    const orig = console.error;
    console.error = () => {};
    try {
      s.subscribe(() => { throw new Error('boom'); });
      s.subscribe(() => { ok++; });
      s.set({ v: 1 });
    } finally { console.error = orig; }
    assert.equal(ok, 1);
  });

  test('shallowEqual', async () => {
    const { shallowEqual } = await mod('store.js');
    assert.ok(shallowEqual({ a: 1, b: 'x' }, { a: 1, b: 'x' }));
    assert.ok(!shallowEqual({ a: 1 }, { a: 1, b: 2 }));
    assert.ok(!shallowEqual({ a: {} }, { a: {} }));
    assert.ok(shallowEqual([1, 2], [1, 2]));
    assert.ok(!shallowEqual([1], { 0: 1 }));
    assert.ok(shallowEqual(null, null));
    assert.ok(!shallowEqual(null, {}));
  });

  test('selectRoute', async () => {
    const { selectRoute } = await mod('store.js');
    const base = { session: { entered: true }, room: null, match: { public: null } };
    assert.equal(selectRoute({ ...base, session: { entered: false } }), 'title');
    assert.equal(selectRoute(base), 'lobby');
    assert.equal(selectRoute({ ...base, room: { code: 'ABCD' } }), 'room');
    assert.equal(selectRoute({ ...base, room: { code: 'ABCD', inMatch: true } }), 'game');
    assert.equal(selectRoute({ ...base, room: { code: 'ABCD' }, match: { public: { phase: 'PREP' } } }), 'game');
    assert.equal(selectRoute({ ...base, room: { code: 'ABCD' }, match: { public: { phase: 'LOBBY' } } }), 'room');
    assert.equal(selectRoute(undefined), 'title');
  });

  test('serverNow applies the clock offset', async () => {
    const { store, serverNow } = await mod('store.js');
    store.set({ clock: { offset: 5000, rtt: 10, synced: true } });
    const d = serverNow() - Date.now();
    assert.ok(d >= 4990 && d <= 5010, `offset applied (${d})`);
    store.set({ clock: { offset: NaN } });
    assert.ok(Math.abs(serverNow() - Date.now()) < 50, 'NaN offset ignored');
    store.set({ clock: { offset: 0, rtt: null, synced: false } });
  });
});

// ---- unit: net --------------------------------------------------------------------------------------------

function fakeTimers(start = 1_000_000) {
  let now = start;
  let seq = 0;
  const q = new Map();
  const add = (fn, ms, every) => { const id = ++seq; q.set(id, { at: now + Math.max(0, ms | 0), fn, every }); return id; };
  return {
    now: () => now,
    setTimeout: (fn, ms) => add(fn, ms, 0),
    clearTimeout: (id) => q.delete(id),
    setInterval: (fn, ms) => add(fn, ms, Math.max(1, ms | 0)),
    clearInterval: (id) => q.delete(id),
    advance(ms) {
      const end = now + ms;
      for (;;) {
        let next = null;
        for (const [id, t] of q) if (t.at <= end && (!next || t.at < next[1].at)) next = [id, t];
        if (!next) break;
        const [id, t] = next;
        now = t.at;
        if (t.every) t.at += t.every; else q.delete(id);
        t.fn();
      }
      now = end;
    },
  };
}

function makeFakeWS() {
  const sockets = [];
  class FakeWS {
    constructor(url) {
      this.url = url;
      this.readyState = 0;
      this.sent = [];
      this.closedWith = null;
      sockets.push(this);
    }
    send(data) {
      if (this.readyState !== 1) throw new Error('not open');
      this.sent.push(JSON.parse(data));
    }
    close(code) { this.readyState = 3; this.closedWith = code ?? 1000; }
    // test helpers
    open() { this.readyState = 1; this.onopen?.(); }
    recv(obj) { this.onmessage?.({ data: typeof obj === 'string' ? obj : JSON.stringify(obj) }); }
    drop(code = 1006) { this.readyState = 3; this.onclose?.({ code }); }
    last(t) { return [...this.sent].reverse().find((m) => m.t === t); }
  }
  return { FakeWS, sockets };
}

async function makeNet(extra = {}) {
  const { Net } = await mod('net.js');
  const timers = fakeTimers();
  const { FakeWS, sockets } = makeFakeWS();
  const net = new Net({ url: 'ws://test/ws', WebSocket: FakeWS, timers, now: timers.now, random: () => 0.5, getToken: () => 'tok-1', ...extra });
  const statuses = [];
  net.on('status', (s) => statuses.push(s.status));
  return { net, timers, sockets, statuses, ws: () => sockets[sockets.length - 1] };
}

/** Connect, open, set a name and complete the handshake. */
async function onlineNet(extra) {
  const ctx = await makeNet(extra);
  ctx.net.setName('凯尔希');
  ctx.ws().open();
  const hello = ctx.ws().last('hello');
  ctx.ws().recv({ t: 'welcome', rid: hello.rid, playerId: 'p_1', token: 'tok-2', name: '凯尔希', serverNow: ctx.timers.now() });
  return ctx;
}

const quiet = async (fn) => {
  const w = console.warn;
  console.warn = () => {};
  try { return await fn(); } finally { console.warn = w; }
};

/** Answer the latest ping on a fake socket. */
function ws0Pong(sock) {
  const p = sock.last('ping');
  if (p) sock.recv({ t: 'pong', c: p.c, s: p.c });
}

describe('net.js', () => {
  test('backoffDelay grows, is capped and jittered', async () => {
    const { backoffDelay, BACKOFF } = await mod('net.js');
    const mid = () => 0.5;
    assert.equal(backoffDelay(0, mid), BACKOFF.base);
    assert.equal(backoffDelay(1, mid), BACKOFF.base * 2);
    assert.equal(backoffDelay(50, mid), BACKOFF.max);
    assert.ok(backoffDelay(3, () => 0) < backoffDelay(3, () => 0.999));
    assert.ok(backoffDelay(-5, mid) >= 100);
    assert.ok(backoffDelay(NaN, mid) >= 100);
  });

  test('errorText / NetError', async () => {
    const { errorText, NetError } = await mod('net.js');
    assert.equal(errorText('ROOM_FULL'), '房间已满');
    assert.equal(errorText('TIMEOUT'), '请求超时，请重试');
    assert.equal(errorText('WHATEVER', 'server says'), 'server says');
    const e = new NetError('NO_FUNDS');
    assert.ok(e instanceof Error);
    assert.equal(e.code, 'NO_FUNDS');
    assert.equal(e.message, '资金不足');
    assert.match(new NetError('BAD_MSG', 'x', 'version mismatch: server 2').message, /版本/);
  });

  test('defaultWsUrl', async () => {
    const { defaultWsUrl } = await mod('net.js');
    assert.equal(defaultWsUrl({ protocol: 'http:', host: 'a:3000' }), 'ws://a:3000/ws');
    assert.equal(defaultWsUrl({ protocol: 'https:', host: 'x.io' }), 'wss://x.io/ws');
  });

  test('connect without a name → connected + ping; setName → hello with token & version', async () => {
    const { PROTOCOL_VERSION } = await import(pathToFileURL(path.join(ROOT, 'shared/constants.js')).href);
    const { net, ws, statuses } = await makeNet();
    net.connect();
    assert.equal(net.status, 'connecting');
    ws().open();
    assert.equal(net.status, 'connected');
    assert.ok(ws().last('ping'), 'latency probe before hello');
    net.setName('  凯尔希  ');
    const hello = ws().last('hello');
    // hello names the state-delta version it understands; a server that does not know the field ignores it.
    const { STATE_DELTA_VERSION } = await import(pathToFileURL(path.join(ROOT, 'shared/stateDelta.js')).href);
    assert.deepEqual({ ...hello, rid: 0 }, {
      t: 'hello',
      rid: 0,
      name: '凯尔希',
      version: PROTOCOL_VERSION,
      delta: STATE_DELTA_VERSION,
      token: 'tok-1',
    });
    assert.equal(net.status, 'handshaking');
    ws().recv({ t: 'welcome', rid: hello.rid, playerId: 'p_1', token: 't', name: '凯尔希', serverNow: Date.now() });
    assert.equal(net.status, 'online');
    assert.equal(net.playerId, 'p_1');
    assert.deepEqual(statuses.slice(0, 2), ['connecting', 'connected']);
    net.setName('凯尔希');
    assert.equal(ws().sent.filter((m) => m.t === 'hello').length, 1, 'same name: no second hello');
    net.setName('阿米娅');
    assert.equal(ws().last('hello').name, '阿米娅', 'rename re-sends hello on the live socket');
  });

  test('token longer than the protocol limit is not sent', async () => {
    const { net, ws } = await makeNet({ getToken: () => 'x'.repeat(65) });
    net.setName('A');
    ws().open();
    assert.equal(ws().last('hello').token, undefined);
  });

  test('request resolves on ok, rejects on error with ERR text', async () => {
    const { net, ws } = await onlineNet();
    const p1 = net.request('room.create', { mode: 'coop', difficulty: 'HARD' });
    const m1 = ws().last('room.create');
    assert.equal(m1.mode, 'coop');
    ws().recv({ t: 'ok', rid: m1.rid });
    assert.equal((await p1).t, 'ok');

    const p2 = net.request('room.join', { code: 'ABCD' });
    const m2 = ws().last('room.join');
    ws().recv({ t: 'error', rid: m2.rid, code: 'ROOM_NOT_FOUND', msg: '…' });
    await assert.rejects(p2, (e) => e.code === 'ROOM_NOT_FOUND' && e.message === '未找到该同盟密钥对应的房间');
    assert.equal(net.pendingCount, 0);
  });

  test('invalid request fails locally with BAD_MSG; hello via request is refused', async () => {
    const { net, ws } = await onlineNet();
    const before = ws().sent.length;
    await quiet(() => assert.rejects(net.request('room.create', { mode: 'pvp', difficulty: 'HARD' }), (e) => e.code === 'BAD_MSG'));
    await assert.rejects(net.request('hello', { name: 'x' }), (e) => e.code === 'BAD_MSG');
    await quiet(() => assert.rejects(net.request('nope', {}), (e) => e.code === 'BAD_MSG'));
    assert.equal(ws().sent.length, before, 'nothing sent');
  });

  test('request times out after 8 s', async () => {
    const { net, timers, ws } = await onlineNet();
    const p = net.request('room.leave', {});
    timers.advance(7999);
    assert.equal(net.pendingCount, 1);
    timers.advance(2);
    await assert.rejects(p, (e) => e.code === 'TIMEOUT');
    assert.equal(net.pendingCount, 0);
    const unhandled = [];
    net.on('unhandledError', (e) => unhandled.push(e.code));
    ws().recv({ t: 'error', rid: ws().last('room.leave').rid, code: 'NOT_IN_ROOM', msg: 'x' });
    assert.deepEqual(unhandled, [], 'late reply to a timed-out request is not reported twice');
  });

  test('requests before a session: OFFLINE when idle, queued while handshaking then flushed', async () => {
    const { net, ws } = await makeNet();
    await assert.rejects(net.request('room.leave', {}), (e) => e.code === 'OFFLINE');
    net.setName('A');
    const p = net.request('room.ready', { ready: true });
    ws().open();
    assert.equal(ws().last('room.ready'), undefined, 'not sent before welcome');
    ws().recv({ t: 'welcome', rid: ws().last('hello').rid, playerId: 'p', token: 't', name: 'A', serverNow: 1 });
    const sent = ws().last('room.ready');
    assert.ok(sent, 'flushed after welcome');
    ws().recv({ t: 'ok', rid: sent.rid });
    await p;
  });

  test('drop → pending rejects, reconnect with backoff, hello again', async () => {
    const { net, ws, sockets, timers } = await onlineNet();
    const p = net.request('room.leave', {});
    ws().drop();
    await assert.rejects(p, (e) => e.code === 'DISCONNECTED');
    assert.equal(net.status, 'reconnecting');
    assert.equal(net.attempt, 1);
    assert.equal(sockets.length, 1);
    timers.advance(499);
    assert.equal(sockets.length, 1);
    timers.advance(2);
    assert.equal(sockets.length, 2, 'reconnected after backoff');
    ws().open();
    assert.equal(ws().last('hello').name, '凯尔希');
    ws().drop();
    assert.equal(net.attempt, 2, 'attempt keeps growing until welcome');
    timers.advance(1001);
    ws().open();
    ws().recv({ t: 'welcome', rid: ws().last('hello').rid, playerId: 'p_1', token: 't', name: '凯尔希', serverNow: 1 });
    assert.equal(net.attempt, 0);
    assert.equal(net.status, 'online');
  });

  test('pong gives latency and clock offset', async () => {
    const { net, ws, timers } = await onlineNet();
    const clocks = [];
    net.on('clock', (c) => clocks.push(c));
    net.probe();
    const ping = ws().last('ping');
    timers.advance(40);
    ws().recv({ t: 'pong', c: ping.c, s: ping.c + 20 + 5000 });
    assert.equal(net.ping, 40);
    assert.equal(net.clockOffset, 5000);
    assert.ok(clocks.at(-1).synced);
    assert.ok(Math.abs(net.serverNow() - (timers.now() + 5000)) <= 1);
    ws().recv({ t: 'pong', c: 'garbage', s: 1 });
    ws().recv({ t: 'pong', c: timers.now() + 99999, s: 1 }); // negative rtt ignored
    assert.equal(net.ping, 40);
  });

  test('silent socket is detected and replaced', async () => {
    const { net, sockets, timers } = await quiet(() => onlineNet());
    await quiet(async () => { timers.advance(20000); });
    assert.equal(sockets[0].closedWith, 4000);
    assert.equal(net.status, 'reconnecting');
  });

  test('throttled background timers (heartbeat ~1/min) do not look like a dead socket', async () => {
    const { timers, sockets, net, ws } = await (async () => {
      const t = fakeTimers();
      const throttled = { ...t, setInterval: (fn) => t.setInterval(fn, 60_000) }; // intensive throttling
      return onlineNet({ timers: throttled, now: t.now }).then((ctx) => ({ ...ctx, timers: t }));
    })();
    for (let i = 0; i < 5; i++) {
      const ping = ws().last('ping');
      timers.advance(30);
      ws().recv({ t: 'pong', c: ping.c, s: ping.c });   // server answers promptly
      timers.advance(60_000 - 30);                        // next (late) heartbeat
    }
    assert.equal(sockets.length, 1, 'no reconnect churn');
    assert.equal(net.status, 'online');
    // …but a socket that really stopped answering is still replaced (at the next late heartbeat).
    await quiet(async () => { timers.advance(130_000); });
    assert.equal(net.status, 'reconnecting');
  });

  test('server close 4001 (session replaced) stops auto-reconnect', async () => {
    const { net, ws, sockets, timers } = await onlineNet();
    const events = [];
    net.on('replaced', (e) => events.push(e.code));
    ws().drop(4001);
    assert.equal(net.status, 'closed');
    assert.deepEqual(events, ['REPLACED']);
    timers.advance(60000);
    assert.equal(sockets.length, 1, 'no reconnect');
    await assert.rejects(net.request('room.leave', {}), (e) => e.code === 'CLOSED');
    net.connect();
    assert.equal(sockets.length, 2, 'manual connect resumes');
  });

  test('server drops an idle pre-hello socket (4002): swapped quietly, no status flicker', async () => {
    const { net, sockets, timers, statuses } = await makeNet();
    net.connect();
    sockets[0].open();
    assert.equal(net.status, 'connected');
    for (let i = 0; i < 10; i++) { ws0Pong(sockets[0]); timers.advance(4000); } // idle on the title, server answers pings
    ws0Pong(sockets[0]);
    const before = statuses.length;
    sockets[0].drop(4002);
    assert.equal(sockets.length, 2, 'fresh socket opened at once');
    assert.equal(net.status, 'connected');
    sockets[1].open();
    assert.equal(net.status, 'connected');
    assert.deepEqual(statuses.slice(before), ['connected'], 'only the (unchanged) connected status is re-emitted');
    net.setName('A');
    assert.ok(sockets[1].last('hello'), 'hello goes out on the new socket');
    // a socket closed with 4002 right after opening is not swapped quietly (no tight loop)
    sockets[1].drop(4002);
    assert.equal(net.status, 'reconnecting');
  });

  test('hello error → connected, helloError, queued requests fail', async () => {
    const { net, ws } = await makeNet();
    const errs = [];
    net.on('helloError', (e) => errs.push(e));
    net.on('unhandledError', () => assert.fail('hello error must not be reported as unhandled'));
    net.setName('A');
    const p = net.request('room.leave', {});
    ws().open();
    ws().recv({ t: 'error', rid: ws().last('hello').rid, code: 'BAD_MSG', msg: 'x', detail: 'version mismatch: server 2' });
    assert.equal(net.status, 'connected');
    assert.equal(errs.length, 1);
    assert.match(errs[0].message, /版本/);
    await assert.rejects(p, (e) => e.code === 'OFFLINE');
  });

  test('pushes are emitted by type and "*"; unsolicited errors as unhandledError; junk ignored', async () => {
    const { net, ws } = await onlineNet();
    const got = [];
    net.on('room.state', (m) => got.push(m.code));
    const all = [];
    const off = net.on('*', (m) => all.push(m.t));
    const unhandled = [];
    net.on('unhandledError', (e) => unhandled.push(e.code));
    ws().recv({ t: 'room.state', code: 'WXYZ', seats: [] });
    ws().recv({ t: 'error', code: 'RATE', msg: 'r' });
    await quiet(async () => { ws().recv('not json'); });
    ws().recv('[1,2]');
    ws().recv({ nope: 1 });
    off();
    ws().recv({ t: 'm.toast', text: 'x' });
    assert.deepEqual(got, ['WXYZ']);
    assert.deepEqual(all, ['room.state', 'error']);
    assert.deepEqual(unhandled, ['RATE']);
  });

  test('a throwing listener does not break dispatch', async () => {
    const { net, ws } = await onlineNet();
    let ok = 0;
    const orig = console.error;
    console.error = () => {};
    try {
      net.on('m.public', () => { throw new Error('boom'); });
      net.on('m.public', () => { ok++; });
      ws().recv({ t: 'm.public', phase: 'PREP', serverNow: 1 });
    } finally { console.error = orig; }
    assert.equal(ok, 1);
  });

  test('send() is fire-and-forget and validated', async () => {
    const { net, ws } = await onlineNet();
    assert.equal(net.send('g.emote', { id: 'autochess_battle_happy' }), true);
    assert.deepEqual(ws().last('g.emote'), { t: 'g.emote', id: 'autochess_battle_happy' });
    await quiet(async () => assert.equal(net.send('g.emote', { id: 'nope' }), false));
    net.close();
    assert.equal(net.send('g.emote', { id: 'autochess_battle_happy' }), false);
    assert.equal(net.status, 'closed');
  });

  test('close() rejects queued requests and stops reconnecting', async () => {
    const { net, sockets, timers } = await makeNet();
    net.setName('A');
    const p = net.request('room.leave', {});
    net.close();
    await assert.rejects(p, (e) => e.code === 'CLOSED');
    timers.advance(60000);
    assert.equal(sockets.length, 1);
  });

  test('constructor failure schedules a retry instead of throwing', async () => {
    const { Net } = await mod('net.js');
    const timers = fakeTimers();
    let n = 0;
    class Boom { constructor() { n++; throw new Error('SecurityError'); } }
    const net = new Net({ url: 'ws://x/ws', WebSocket: Boom, timers, now: timers.now, random: () => 0.5 });
    await quiet(async () => { net.connect(); timers.advance(600); });
    assert.equal(n, 2);
    assert.equal(net.status, 'reconnecting');
    net.close();
  });
});

