// ---- multi-device / browser compatibility (static) -----------------------------------------------------------------
// Supported: desktop Chrome / Edge / Firefox (incl. ESR 115) / Safari 15+, iPadOS / iOS 15+ Safari, Android Chrome.
// Guards against syntax and CSS features that silently break those (a lookbehind regex is a SyntaxError in Safari
// < 16.4 and stops the whole client; :has() / container queries / CSS nesting are ignored by Firefox ESR 115 or Safari
// 15; color-mix() by Safari < 16.2; backdrop-filter needs its -webkit- twin before Safari 18).

const CSS_FILES = walk(path.join(PUBLIC, 'css'), '.css');
const BROWSER_JS = [...JS_FILES, ...walk(path.join(ROOT, 'shared'), '.js'), ...walk(path.join(ROOT, 'server/sim'), '.js').filter((f) => !/nodeData\.js$/i.test(f))];
/** Rules of a stylesheet as { selector, body } (flat; @media blocks are walked into). */
function cssRules(src) {
  const out = [];
  const clean = src.replace(/\/\*[\s\S]*?\*\//g, '');
  const re = /([^{}]+)\{([^{}]*)\}/g;
  let m;
  while ((m = re.exec(clean))) out.push({ selector: m[1].trim(), body: m[2] });
  return out;
}

describe('multi-device & browser compatibility (static)', () => {
  const index = readFileSync(path.join(PUBLIC, 'index.html'), 'utf8');

  test('index.html: landscape viewport without page zoom, notch-aware, devices.css last, boot diagnostics', () => {
    const vp = index.match(/<meta name="viewport" content="([^"]+)"/)?.[1] || '';
    for (const k of ['width=device-width', 'initial-scale=1', 'maximum-scale=1', 'user-scalable=no', 'viewport-fit=cover']) assert.ok(vp.includes(k), `viewport has ${k}`);
    const sheets = [...index.matchAll(/<link rel="stylesheet" href="(\/css\/[^"]+)"/g)].map((x) => x[1]);
    assert.equal(sheets[sheets.length - 1], '/css/devices.css', 'devices.css is the last stylesheet');
    assert.match(index, /<script nomodule src="\/js\/bootLegacy\.js">/, 'a browser without ES modules gets the external fallback');
    const boot = readFileSync(path.join(PUBLIC, 'js/boot.js'), 'utf8');
    const legacy = readFileSync(path.join(PUBLIC, 'js/bootLegacy.js'), 'utf8');
    assert.match(legacy, /__spBootFail\('old'\)/);
    assert.match(boot, /addEventListener\('error'/, 'module loading errors are caught under CSP');
    assert.match(boot, /__spBootFail\('load'\)/);
    assert.ok(!/\sonerror=/.test(index), 'no inline event handler under CSP');
    assert.match(index, /apple-mobile-web-app-capable/);
    assert.match(index, /class="rotate-hint"/);
  });

  test('main.js imports the polyfills before anything else and installs the device layer', () => {
    const src = readFileSync(path.join(PUBLIC, 'js/main.js'), 'utf8');
    const first = staticImports(src)[0];
    assert.equal(first?.spec, './ui/compat.js');
    assert.match(src, /installDeviceSupport\(\)/);
  });

  test('client modules use no bare specifiers (import maps need Safari 16.4+) — ui/fieldHost.js included', () => {
    // (the vendored hooks.module.js is rewritten by tools/vendor.mjs to import "./preact.module.js" — see the vendor
    // test below; the import map stays for pages that still name "preact" / "htm")
    for (const file of JS_FILES) {
      const rel = path.relative(path.join(PUBLIC, 'js'), file).split(path.sep).join('/');
      for (const { spec } of staticImports(readFileSync(file, 'utf8'))) {
        assert.match(spec, /^(\.{1,2}\/|\/)/, `${rel}: bare specifier '${spec}'`);
      }
    }
  });

  test('vendored ES modules import no bare specifiers (hooks → ./preact.module.js, the URL the import map names)', async () => {
    const { rewriteBare, VENDOR_REWRITES } = await import('../tools/vendor.mjs');
    assert.equal(rewriteBare('import{options as n}from"preact";', { preact: './preact.module.js' }), 'import{options as n}from"./preact.module.js";');
    assert.equal(rewriteBare("import { h } from 'preact'; import('preact')", { preact: './p.js' }), "import { h } from './p.js'; import('./p.js')");
    assert.equal(rewriteBare('from"preact/hooks";from"preactx"', { preact: './p.js' }), 'from"preact/hooks";from"preactx"', 'only the exact specifier');
    assert.deepEqual(VENDOR_REWRITES['hooks.module.js'], { preact: './preact.module.js' });
    for (const f of ['hooks.module.js', 'preact.module.js', 'htm.module.js']) {
      const file = path.join(PUBLIC, 'vendor', f);
      if (!existsSync(file)) continue;
      for (const { spec } of staticImports(readFileSync(file, 'utf8'))) assert.match(spec, /^(\.{1,2}\/|\/)/, `vendor/${f}: bare specifier '${spec}' (run npm run vendor)`);
    }
  });

  test('no regex lookbehind in code that runs in the browser (SyntaxError in Safari < 16.4)', () => {
    for (const file of BROWSER_JS) {
      const src = readFileSync(file, 'utf8').replace(/\/\/[^\n]*|\/\*[\s\S]*?\*\//g, '');
      assert.doesNotMatch(src, /\(\?<[=!]/, `${path.relative(ROOT, file)} uses a lookbehind`);
    }
  });

  test('APIs newer than Safari 15.0 / Firefox ESR are polyfilled by ui/compat.js', () => {
    const compat = readFileSync(path.join(PUBLIC, 'js/ui/compat.js'), 'utf8');
    const needs = { 'Object.hasOwn': 'hasOwn', '.at(': "'at'", structuredClone: 'structuredClone', '.findLast(': 'findLast' };
    for (const file of BROWSER_JS) {
      const src = readFileSync(file, 'utf8');
      for (const [api, mark] of Object.entries(needs)) {
        if (src.includes(api)) assert.ok(compat.includes(mark), `${path.relative(ROOT, file)} uses ${api}: compat.js must polyfill it`);
      }
      // never polyfillable: these would break Safari 15 / Firefox ESR outright
      for (const bad of ['Object.groupBy', 'Promise.withResolvers', 'Array.fromAsync', 'Iterator.from', '.toSorted(', '.toReversed(', '.toSpliced(', 'Set.prototype.union', '.union(']) {
        assert.ok(!src.includes(bad), `${path.relative(ROOT, file)} uses ${bad}`);
      }
    }
  });

  test('CSS: no :has(), container queries, @layer or nesting; prefixed backdrop-filter; color-mix() has a fallback', () => {
    for (const file of CSS_FILES) {
      const rel = path.relative(ROOT, file);
      const src = readFileSync(file, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
      assert.doesNotMatch(src, /:has\(/, `${rel}: :has() (Firefox ESR 115, Safari < 15.4)`);
      assert.doesNotMatch(src, /@container|container-type|@layer/, `${rel}: container queries / cascade layers`);
      for (const r of cssRules(src)) {
        assert.ok(!/(^|[\s,])&/.test(r.selector), `${rel}: CSS nesting in '${r.selector}'`);
        const decls = r.body.split(';').map((d) => d.trim()).filter(Boolean);
        decls.forEach((d, i) => {
          const prop = d.split(':')[0].trim();
          if (prop === 'backdrop-filter') assert.ok(decls.some((x) => x.startsWith('-webkit-backdrop-filter')), `${rel} '${r.selector}': backdrop-filter without -webkit- twin`);
          if (/color-mix\(/.test(d)) {
            const fallback = decls.slice(0, i).some((x) => x.split(':')[0].trim() === prop && !/color-mix\(/.test(x));
            assert.ok(fallback, `${rel} '${r.selector}': ${prop} uses color-mix() without a fallback before it`);
          }
        });
      }
    }
  });

  test('devices.css: safe-area insets for the HUD and screens, touch-action, hit areas, overscroll', () => {
    const src = readFileSync(path.join(PUBLIC, 'css/devices.css'), 'utf8');
    for (const k of ['safe-area-inset-left', 'safe-area-inset-right', 'safe-area-inset-top', 'safe-area-inset-bottom']) assert.ok(src.includes(k), k);
    assert.match(src, /\.gm__hud \{[^}]*var\(--sa-l\)/);
    assert.match(src, /\.screen:not\(\.gm\) \{[^}]*var\(--sa-t\)/);
    assert.match(src, /overscroll-behavior: none/);
    assert.match(src, /touch-action: none/);
    assert.match(src, /width: max\(100%, var\(--tap-min\)\)/);
    assert.match(src, /--tap-min: 44px/);
  });
});

describe('explicit local match recovery (#431)', () => {
  async function recoveryPair() {
    const { createIdentity } = await mod('net.js');
    const local = memStorage(), hub = channelHub(), ownerSession = memStorage(), guestSession = memStorage();
    const ownerChannel = hub.create();
    const owner = createIdentity({ local, session: ownerSession, tabId: 'z-owner', channel: ownerChannel, queryMs: 5, now: () => 100 });
    const guest = createIdentity({ local, session: guestSession, tabId: 'a-guest', channel: hub.create(), queryMs: 5, now: () => 200 });
    await owner.init(); owner.saveToken('seat-owner'); owner.rememberMatch({ name: 'Owner', code: 'ROOM1' });
    await guest.init(); guest.saveToken('seat-guest');
    return { createIdentity, local, hub, ownerSession, guestSession, ownerChannel, owner, guest, id: guest.recoverable()[0].id };
  }
  test('live: a smaller tab id cannot reclaim an active seat', async () => {
    const { guest, owner, id } = await recoveryPair();
    assert.equal(await guest.resume(id), false);
    assert.equal(guest.getToken(), 'seat-guest');
    assert.equal(owner.getToken(), 'seat-owner');
  });
  test('reload: the original session wins over a recovery attempt during navigation', async () => {
    const p = await recoveryPair();
    p.ownerChannel.close();
    assert.equal(await p.guest.resume(p.id), true, 'old document is gone');
    const reloaded = p.createIdentity({ local: p.local, session: p.ownerSession, tabId: 'zz-reloaded', channel: p.hub.create(), queryMs: 5 });
    assert.equal(await reloaded.init(), 'seat-owner');
    assert.equal(p.ownerSession.getItem('sp.token'), 'seat-owner');
    assert.equal(p.guest.getToken(), 'seat-guest', 'unconfirmed recovery yields before hello');
  });
  test('midInit: the session token answers claims before init finishes', async () => {
    const p = await recoveryPair();
    p.ownerChannel.close();
    let finish;
    const reloaded = p.createIdentity({ local: p.local, session: p.ownerSession, tabId: 'zz-reloaded', channel: p.hub.create(), setTimeout: (fn) => { finish = fn; } });
    const pending = reloaded.init();
    assert.equal(await p.guest.resume(p.id), false);
    finish();
    assert.equal(await pending, 'seat-owner');
    assert.equal(p.ownerSession.getItem('sp.token'), 'seat-owner');
    assert.equal(p.guest.getToken(), 'seat-guest');
  });
  test('an occupied session token never falls back to a different recent identity', async () => {
    const p = await recoveryPair();
    p.local.setItem('sp.tokens', JSON.stringify(['seat-free', 'seat-owner']));
    const duplicate = p.createIdentity({ local: p.local, session: p.ownerSession.clone(), tabId: '0-copy', channel: p.hub.create(), queryMs: 5 });
    assert.equal(await duplicate.init(), null);
    assert.equal(duplicate.getToken(), null);
  });
  test('resume persists neither its token nor a welcome stamp until the server welcomes it', async () => {
    const p = await recoveryPair();
    p.ownerChannel.close();
    const stamp = p.guestSession.getItem('sp.tokenWelcome');
    assert.equal(await p.guest.resume(p.id), true);
    assert.equal(p.guestSession.getItem('sp.token'), 'seat-guest');
    assert.equal(p.guestSession.getItem('sp.tokenWelcome'), stamp);
    p.guest.saveToken('seat-owner');
    assert.equal(p.guestSession.getItem('sp.token'), 'seat-owner');
    assert.ok(p.guestSession.getItem('sp.tokenWelcome'));
  });
  test('an earlier welcome stamp survives reload and beats a later live welcome', async () => {
    const p = await recoveryPair();
    p.ownerChannel.close();
    assert.equal(await p.guest.resume(p.id), true);
    p.guest.saveToken('seat-owner'); // recovery's welcome is later than the original owner's
    const originalStamp = p.ownerSession.getItem('sp.tokenWelcome');
    const reloaded = p.createIdentity({ local: p.local, session: p.ownerSession, tabId: 'zz-reloaded', channel: p.hub.create(), queryMs: 5, now: () => 300 });
    assert.equal(await reloaded.init(), 'seat-owner');
    reloaded.saveToken('seat-owner');
    assert.equal(p.ownerSession.getItem('sp.tokenWelcome'), originalStamp, 'reconnect does not reset seniority');
  });
  test('a welcome received during init cannot be overwritten or erased by its pending result', async () => {
    const { createIdentity } = await mod('net.js');
    const local = memStorage(), session = memStorage(), hub = channelHub();
    session.setItem('sp.token', 'old');
    let finish;
    const id = createIdentity({ local, session, channel: hub.create(), setTimeout: (fn) => { finish = fn; } });
    const pending = id.init();
    id.saveToken('new'); finish();
    assert.equal(await pending, 'new');
    assert.equal(session.getItem('sp.token'), 'new');
  });
  test('an idle tab can reclaim a closed match tab without taking a live one', async () => {
    const { createIdentity } = await mod('net.js');
    const local = memStorage(), hub = channelHub(), ca = hub.create(), cb = hub.create();
    const a = createIdentity({ local, session: memStorage(), tabId: 'a', channel: ca, queryMs: 5 });
    const b = createIdentity({ local, session: memStorage(), tabId: 'b', channel: cb, queryMs: 5 });
    await a.init(); a.saveToken('idle-token');
    await b.init(); b.saveToken('match-token'); b.rememberMatch({ name: 'Doctor B', code: 'ABC123' });
    const [item] = a.recoverable();
    assert.equal(item.name, 'Doctor B');
    assert.equal(JSON.stringify(item).includes('match-token'), false);
    assert.equal(await a.resume(item.id), false, 'live original keeps its seat');
    assert.equal(a.getToken(), 'idle-token');
    cb.close();
    assert.equal(await a.resume(item.id), true);
    assert.equal(a.getToken(), 'match-token');
