    }
  });

  test('404 page, HEAD, 405, bare mount redirect, healthz', async () => {
    const nf = await httpReq(srv.port, '/nope.js');
    assert.equal(nf.status, 404);
    assert.match(nf.headers['content-type'], /^text\/html/);
