    assert.deepEqual((await httpReq(srv.port, '/js/app.js', { headers: { 'accept-encoding': 'br' } })).body, br.body);

    const plain = await httpReq(srv.port, '/js/app.js');
    assert.equal(plain.headers['content-encoding'], undefined);
