    ps.endlessDeployCapBonus = 1;
    assert.ok(ps.move(piece.uid, { area: 'board', row: at[0], col: at[1] }).ok);
    assert.equal(ps.deployCount, 13);
    h.invariants();
  } finally { h.m.dispose(); }
});

