// `log` keeps every sent frame; `battles` every local battle by battleId.

import assert from 'node:assert/strict';
import { createBattleFromSpec, compactResult, battleProgress, attachLpMeter } from '../../server/sim/spec.js';
import { RehearsalRun } from '../../server/sim/rehearsal.js';
import { validateC2S } from '../../shared/protocol.js';
import { TICK } from '../../server/sim/constants.js';

const SLICE_MS = 250;

export class SimClient {
  constructor(playerId, o) {
    this.playerId = playerId;
    this.o = { pace: 'instant', speed: 2, ...o };
    this.log = [];
    /** @type {Map<string, { battle: any, spec: any, authoritative: boolean, meter: any, timer: any, finished: boolean, sentResult: boolean }>} */
    this.battles = new Map();
    this.starts = [];
    this.ends = [];
    this.pools = [];
  }

  send(msg) {
    const bad = validateC2S(msg);
    assert.equal(bad, null, `${this.playerId} would send an invalid ${msg.t}: ${bad}`);
    this.log.push(msg);
    this.o.send(msg);
  }

  /** Stop every timer (the page closed). */
  close() {
    this.closed = true;
    for (const e of this.battles.values()) if (e.timer) { this.o.clearTimeout(e.timer); e.timer = null; }
  }

  onMessage(msg) {
    if (!msg || typeof msg !== 'object' || this.closed) return;
    if (msg.t === 'b.start') this._start(msg);
    else if (msg.t === 'b.pool') this._pool(msg);
    else if (msg.t === 'b.end') this._end(msg);
  }

  _start(msg) {
    this.starts.push(msg);
    const cur = this.battles.get(msg.battleId);
    if (cur) { // resend (reconnect / watch back / authority handover): keep the running battle
      const was = cur.authoritative;
      cur.authoritative = !!msg.authoritative;
      if (cur.authoritative && !was) {
        // a replica promoted to authority (handover): it ran live in a browser — catch up to the field's clock
        this._stepTo(cur, Number(msg.elapsed) || 0);
        this._schedule(cur, 0);
      }
      return;
    }
    const entry = { spec: msg.spec, battleId: msg.battleId, fieldId: msg.fieldId, authoritative: !!msg.authoritative, finished: false, sentResult: false, timer: null, lastProgress: -Infinity };
    entry.battle = createBattleFromSpec(msg.spec, this.o.ds, { BattleClass: this.o.BattleClass, recordEvents: false, quiet: true });
    entry.meter = attachLpMeter(entry.battle);
    this.battles.set(msg.battleId, entry);
    // catch up to the field's clock (reconnect / observing a running field)
    const target = Number(msg.elapsed) || 0;
    if (target > 0) this._stepTo(entry, target);
    if (entry.authoritative) this._schedule(entry, this.o.delayMs || 0);
  }

  _pool(msg) {
    this.pools.push(msg);
    for (const e of this.battles.values()) {
      const pool = e.battle.sharedBoss;
      if (pool && typeof pool.sync === 'function') pool.sync(msg.hp, msg.acked ? msg.acked[e.fieldId] : undefined, msg.max);
    }
  }

  _end(msg) {
    this.ends.push(msg);
    const e = this.battles.get(msg.battleId);
    if (!e) return;
    if (msg.reason === 'takeover') { e.authoritative = false; if (e.timer) this.o.clearTimeout(e.timer); e.timer = null; return; }
    try { e.battle.forceEnd(msg.reason === 'timeout' ? 'timeout' : 'forced'); } catch { /* ignore */ }
    if (e.authoritative) this._schedule(e, 0);
  }

  _stepTo(e, gt) {
    const b = e.battle;
    const cap = Math.ceil(gt / TICK);
    while (!b.finished && (b.tickCount ?? Math.round(b.time / TICK)) < cap) b.step();
  }

  _schedule(e, ms) {
    if (e.timer) this.o.clearTimeout(e.timer);
    e.timer = this.o.setTimeout(() => { e.timer = null; this._slice(e); }, ms);
  }

  _slice(e) {
    if (this.closed || !e.authoritative || e.sentResult || this.o.mute) return;
    const b = e.battle;
    const bossLike = e.spec.kind === 'boss' || e.spec.kind === 'hidden';
    if (this.o.pace === 'instant' && !bossLike) {
      let n = 0;
      while (!b.finished && n++ < 200_000) b.step();
    } else {
      const ticks = Math.max(1, Math.round(((this.o.speed || 2) * SLICE_MS) / 1000 / TICK));
      for (let i = 0; i < ticks && !b.finished; i++) b.step();
    }
    this._progress(e);
    if (b.finished) {
      if (this.o.stall) return;
      let result = compactResult(b.result());
      if (this.o.tamper) result = this.o.tamper(result, e.spec);
      e.sentResult = true;
      const cs = typeof this.o.withCs === 'function' ? this.o.withCs(e.spec) : this.o.withCs ? e.spec.cs : undefined;
      this.send({ t: 'b.result', battleId: e.battleId, result, ...(cs ? { cs } : {}) });
      return;
    }
    this._schedule(e, SLICE_MS);
  }

  _progress(e) {
    const p = battleProgress(e.battle);
    const msg = { t: 'b.progress', battleId: e.battleId, gt: p.gt, killed: Math.min(p.killed, p.total), total: p.total, done: p.done };
    // the HUD capsule's numerator, like public/js/battle/runner.js (kept only when the battle reports one)
    if (Number.isFinite(p.resolved)) msg.resolved = Math.min(p.resolved, p.total);
    const bossLike = e.spec.kind === 'boss' || e.spec.kind === 'hidden';
    if (bossLike) {
      const pool = e.battle.sharedBoss;
      msg.leaks = e.meter.lp;
      if (p.leaksBy) msg.leaksBy = p.leaksBy; // like public/js/battle/runner.js
      msg.bossDmg = pool && Number.isFinite(pool.cum) ? pool.cum : 0;
      if (pool && pool.byPlayer) msg.by = { ...pool.byPlayer };
    } else {
      msg.leaks = p.leaks;
      // 联防: the leakers' enemies still standing (like public/js/battle/runner.js)
      if (p.left) msg.left = Object.fromEntries(Object.entries(p.left).slice(0, 4));
    }
    this.send(msg);
  }
}

/**
 * Attach SimClients to a harness match (test/match/harness.js makeMatch): every human gets one; frames sent to a
 * disconnected / departed human are dropped (like the platform). Returns Map playerId → SimClient.
 */
export function attachSimClients(h, opts = {}) {
  const clients = new Map();
  const m = h.m;
  for (const ps of m.players.values()) {
    if (ps.isBot) continue;
    const c = new SimClient(ps.playerId, {
      send: (msg) => { const r = m.handle(ps.playerId, msg); if (r && r.error && opts.onError) opts.onError(ps.playerId, msg, r); },
      setTimeout: (fn, ms) => h.sched.setTimeout(fn, ms),
      clearTimeout: (t) => h.sched.clearTimeout(t),
      ds: m.ds,
      BattleClass: opts.BattleClass,
      speed: m.gameSpeed,
      ...(opts.perPlayer && opts.perPlayer[ps.playerId] ? opts.perPlayer[ps.playerId] : {}),
      pace: (opts.perPlayer && opts.perPlayer[ps.playerId] && opts.perPlayer[ps.playerId].pace) || opts.pace || 'instant',
    });
    clients.set(ps.playerId, c);
  }
  const HANDLED = new Set(['b.start', 'b.pool', 'b.end']);
  const pending = new Set();
  const deliver = (c, ps, msg) => {
    // delivered after the server call that produced it (a real socket is never re-entrant)
    const t = h.sched.setTimeout(() => { pending.delete(t); if (ps.connected && !ps.left) c.onMessage(msg); }, 0);
    pending.add(t);
  };
  h.onSend.push((pid, msg) => {
    const c = clients.get(pid);
    const ps = m.players.get(pid);
    if (!c || !ps || !ps.connected || ps.left || !HANDLED.has(msg.t)) return;
    deliver(c, ps, msg);
  });
  h.onBroadcast.push((msg) => {
    if (!HANDLED.has(msg.t)) return;
    for (const [pid, c] of clients) {
      const ps = m.players.get(pid);
      if (!ps || !ps.connected || ps.left) continue;
      deliver(c, ps, msg);
    }
  });
  /** Close every client (pending deliveries and battle timers are dropped). */
  clients.closeAll = () => {
    for (const t of pending) h.sched.clearTimeout(t);
    pending.clear();
    for (const c of clients.values()) c.close();
  };
  return clients;
}

/**
 * A SimClient behind a websocket test client (test/helpers/wsClient.js TestClient): frames are read from the socket,
 * reports go out without a rid (fire-and-forget, like the browser runner). Real timers.
 * @returns {SimClient}
 */
export function attachWsSimClient(tc, opts = {}) {
  const sc = new SimClient(tc.id, {
    send: (msg) => { if (tc.isOpen) tc.send({ ...msg, rid: null }); },
    setTimeout: (fn, ms) => setTimeout(fn, ms),
    clearTimeout: (t) => clearTimeout(t),
    ...opts,
  });
  tc.ws.on('message', (data, isBinary) => {
    if (isBinary) return;
    let msg;
    try { msg = JSON.parse(String(data)); } catch { return; }
    try { sc.onMessage(msg); } catch (e) { sc.error = e; }
  });
  return sc;
}

// ---------------------------------------------------------------------------------------------------
// Delegated bot layout rehearsals (DESIGN §14)

/**
 * The pick of one `b.rehearsal` task, computed the way the page's Worker does it (public/js/battle/rehearsalWorker.js):
 * build every candidate with the shared sim (a factory per candidate, so the run builds them as it reaches them — what
 * the server's own job does too), run them with the shared comparison (server/sim/rehearsal.js) and return the winning
 * index.
 * @param {{ playerId: string, cap: number, limits?: { stage: number, tickBudget: number }, specs: object[] }} task
 * @param {any} ds DataSource of the match (the same data the server simulates with)
 * @param {{ BattleClass?: Function }} [opts]
 */
export function simulateRehearsal(task, ds, { BattleClass } = {}) {
  const run = new RehearsalRun(task.specs.map((spec) => () => createBattleFromSpec(spec, ds, { BattleClass, quiet: true, recordEvents: false })), task.playerId, task.cap, task.limits || {});
  run.run();
  return run.score.index;
}

/**
 * A scripted host browser for delegated bot rehearsals: every `b.rehearsal` frame sent to a watched player (default:
 * every human seat) is answered through `m.handle` — after `delayMs` (0: a virtual timer, like a socket — the server
 * call that sent the frame has returned by then), or right inside that call with `sync` (the other extreme: the answer
 * beats the driver's callback) — with the pick the page's Worker would make (simulateRehearsal). Every
 * `b.rehearsalCancel` of a watched player is collected in `host.cancels` (the frame the page drops a task on). Test
 * knobs: `mute` (never answer), `error` (this browser cannot run the task), `tamper(frame) → any` (a wrong or malformed
 * answer), `manual` (collect the frames and answer with `host.answer(task, fields)`, e.g. after the server already took
 * the task over).
 * @param {ReturnType<import('./harness.js').makeMatch>} h
 * @param {{ players?: string[]|null, mute?: boolean, error?: boolean, delayMs?: number, tamper?: Function|null,
 *   manual?: boolean, sync?: boolean, ds?: any, BattleClass?: Function }} [o]
 */
export function attachRehearsalHost(h, { players = null, mute = false, error = false, delayMs = 0, tamper = null, manual = false, sync = false, ds = null, BattleClass = undefined } = {}) {
  const m = h.m;
  const host = { tasks: [], cancels: [], answered: 0 };
  const watched = (pid) => (players ? players.includes(pid) : !m.players.get(pid)?.isBot);
  h.onSend.push((pid, msg) => {
    if (!watched(pid)) return;
    if (msg.t === 'b.rehearsalCancel') { host.cancels.push(msg.taskId); return; }
    if (msg.t !== 'b.rehearsal') return;
    const task = { playerId: pid, frame: msg };
    host.tasks.push(task);
    if (manual || mute) return;
    const reply = () => {
      const choice = tamper ? tamper(msg) : simulateRehearsal(msg, ds || m.ds, { BattleClass });
      host.answered++;
      m.handle(pid, { t: 'b.rehearsalResult', taskId: msg.taskId, ...(error ? { error: true } : { choice }) });
    };
    if (sync) reply(); else h.sched.setTimeout(reply, delayMs);
  });
  /** Answer one collected task by hand (manual mode, or a late answer after a takeover). */
  host.answer = (task, fields = {}) => { host.answered++; return m.handle(task.playerId, { t: 'b.rehearsalResult', taskId: task.frame.taskId, ...fields }); };
  return host;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { PHASE } from '../../shared/constants.js';
import { makeMatch } from './harness.js';
import { FakeBattle } from './fakeBattle.js';
import { validateC2S } from '../../shared/protocol.js';
import { nextUnitePlan } from '../../server/match/unite.js';

test('a unite progress frame reports every leaker in a twenty-player match', () => {
  const left = Object.fromEntries(Array.from({ length: 20 }, (_, i) => [`p_${i}`, i + 1]));
  const msg = { t: 'b.progress', battleId: 'unite', gt: 1, killed: 0, total: 20, left };
  assert.equal(validateC2S(msg), null);
  assert.notEqual(validateC2S({ ...msg, left: { ...left, p_20: 1 } }), null);
});

for (const clientCombat of [false, true]) {
  test(`eight players: two ${clientCombat ? 'client' : 'server'} unite waves use four unique helpers and final survivors`, () => {
    const waveSeeds = new Map();
    const h = makeMatch({ humans: 8, fake: true, clientCombat, seed: 707,
      script: (battle) => {
        if (battle.kind === 'normal') return { leaks: { p_0: 6 } };
        if (battle.kind === 'unite') {
          if (!waveSeeds.has(battle.opts.seed)) waveSeeds.set(battle.opts.seed, waveSeeds.size + 1);
          const first = waveSeeds.get(battle.opts.seed) === 1;
          const helper = battle.players[0];
          return { survivors: { p_0: first ? 3 : 1 }, coins: { [helper]: first ? 5 : 7 }, damage: { [helper]: first ? 123 : 456 } };
        }
        return {};
      },
    }).start();
    const m = h.m;
    h.toPrep(1);
    h.ps('p_0').lp = 30;
    h.drive(() => m.phase === PHASE.UNITE && m.unitePlan.round === 1);
    const first = m.unitePlan.helpers.map((p) => p.playerId);
    assert.deepEqual(first, ['p_1', 'p_2']);
    assert.deepEqual(m.unitePlan.reserveHelpers.map((p) => p.playerId), ['p_3', 'p_4']);
    assert.deepEqual([m.publicView().unite.round, m.publicView().unite.roundsMax], [1, 2]);
    h.drive(() => m.phase === PHASE.UNITE && m.unitePlan.round === 2);
    const second = m.unitePlan.helpers.map((p) => p.playerId);
    assert.deepEqual(second, ['p_3', 'p_4']);
    assert.equal(new Set([...first, ...second]).size, 4);
    assert.equal(m.unitePlan.leaked.length, 3, 'only first-wave survivors re-enter');
    assert.deepEqual([m.publicView().unite.round, m.publicView().unite.roundsMax], [2, 2]);
    h.drive(() => m.phase === PHASE.SETTLE);
    assert.equal(new Set(FakeBattle.instances.filter((b) => b.kind === 'unite').map((b) => b.opts.seed)).size, 2);
    assert.equal(h.ps('p_0').lp, 29, 'only the final survivor costs the original leaker LP');
    assert.equal(h.ps('p_1').pendingFunds, 5, 'first-wave bounty credits survive second-wave settlement');
    assert.equal(h.ps('p_3').pendingFunds, 7);
    assert.ok(h.ps('p_1').stats.dmgDealt >= 123 && h.ps('p_3').stats.dmgDealt >= 456);
    assert.deepEqual(m.publicView().uniteResult, {
      through: 1, helpers: [...first, ...second], leakers: ['p_0'],
      losses: Object.fromEntries(m.order.map((p) => [p.playerId, p.playerId === 'p_0' ? 1 : 0])),
    }, 'the upstream result dialog reports both waves and the actual final LP charge');
    h.invariants();
    m.dispose();
  });
}

for (const n of [7, 8, 20]) {
  test(`${n} players: unite stops when only one helper exists or the first wave clears`, () => {
    const h = makeMatch({ humans: n, fake: true, seed: 708,
      script: (battle) => battle.kind === 'normal' ? { leaks: { p_0: 3 } } : {},
    }).start();
    const m = h.m;
    h.toPrep(1);
    h.drive(() => m.phase === PHASE.SETTLE);
    assert.equal(FakeBattle.instances.filter((b) => b.kind === 'unite').length, 1);
    assert.equal(h.ps('p_0').stats.lpLost, 0);
    h.invariants();
    m.dispose();
  });
}

test('second unite wave preserves duplicate enemies by source and mods and respects a one-helper wave limit', () => {
  const leak = (sourcePlayerId, rank, coins) => ({ enemyKey: 'enemy_a', sourcePlayerId, tag: null,
    mods: { rank }, lpr: 1, bounty: { coins, ownerPlayerId: sourcePlayerId } });
  const plan = { round: 1, roundsMax: 2, perRound: 1, helpers: [{ playerId: 'h_0' }],
    reserveHelpers: [{ playerId: 'h_1', alive: true, left: false }, { playerId: 'h_2', alive: true, left: false }],
    leakers: [{ playerId: 'p_0' }, { playerId: 'p_1' }], notReentered: new Map(),
    leaked: [leak('p_0', 1, 3), leak('p_0', 2, 5), leak('p_1', 1, 7)], history: [], usedHelpers: [] };
  const result = { unspawned: [{ enemyKey: 'enemy_a', sourcePlayerId: 'p_0', tag: null }],
    perPlayer: { h_0: { leaked: [
      { enemyKey: 'enemy_a', sourcePlayerId: 'p_0', tag: null, mods: { rank: 2 } },
      { enemyKey: 'enemy_a', sourcePlayerId: 'p_1', tag: null, mods: { rank: 1 } },
    ] } } };
  const next = nextUnitePlan(plan, result);
  assert.deepEqual(nextUnitePlan(plan, result, 7), next,
    'the old living-player argument no longer lowers the opening groups\' fixed limit');
  assert.deepEqual(next.helpers.map((p) => p.playerId), ['h_1']);
  assert.deepEqual(next.reserveHelpers.map((p) => p.playerId), ['h_2']);
  assert.deepEqual(next.leaked.map((l) => [l.sourcePlayerId, l.mods.rank, l.bounty.coins]),
    [['p_0', 1, 3], ['p_0', 2, 5], ['p_1', 1, 7]]);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ERR, PHASE } from '../../shared/constants.js';
import { validateC2S } from '../../shared/protocol.js';
import { makeMatch } from './harness.js';
import { FakeBattle } from './fakeBattle.js';

const voteMsg = { t: 'g.uniteSkipVote' };
function voteMatch({ humans = 3, bots = 8 - humans, clientCombat = false, beforeCombat = () => {} } = {}) {
  const h = makeMatch({ humans, bots, clientCombat, fake: true, seed: 707, spectators: ['viewer'],
    script: (b) => b.kind === 'normal' ? { leaks: { p_0: 6 } }
      : b.kind === 'unite' ? { survivors: { p_0: 3 }, coins: { [b.players[0]]: 5 } } : {},
  }).start();
  h.toPrep(1);
  beforeCombat(h);
  assert.ok(h.drive(() => h.m.phase === PHASE.UNITE && h.m.unitePlan.round === 1));
  return h;
}

test('the skip vote is a validated game intent', () => {
  assert.equal(validateC2S(voteMsg), null);
  assert.equal(validateC2S({ ...voteMsg, voteId: 'unite:match-1:1:3' }), null);
  for (const voteId of ['', 'bad id', 'a'.repeat(65), null, 3]) {
    assert.notEqual(validateC2S({ ...voteMsg, voteId }), null);
  }
});

for (const clientCombat of [false, true]) {
  for (const humans of [1, 2, 3, 4, 5, 8]) {
    test(`${clientCombat ? 'client' : 'server'} unite: ${humans} humans require strictly more than half to skip`, () => {
      const h = voteMatch({ humans, clientCombat });
      const m = h.m;
      const needed = Math.floor(humans / 2) + 1;
      assert.equal(m.publicView().unite.skipVote.needed, needed);
      assert.equal(m.publicView().unite.skipVote.eligible.length, humans);
      for (let i = 0; i < needed; i++) {
        assert.deepEqual(m.handle(`p_${i}`, voteMsg), { ok: true });
        assert.equal(m.unitePlan.skipRemaining, i + 1 === needed);
        m.handle(`p_${i}`, voteMsg);
        assert.equal(m.publicView().unite.skipVote.voters.length, i + 1, 'duplicate vote does not add a ballot');
      }
      assert.equal(m.phase, PHASE.UNITE, 'approval never interrupts the first wave');
      h.drive(() => m.phase === PHASE.SETTLE);
      assert.equal(new Set(FakeBattle.instances.filter((b) => b.kind === 'unite').map((b) => b.opts.seed)).size, 1);
      assert.equal(h.ps('p_0').stats.lpLost, 3, 'first-wave survivors still cost LP');
      const firstHelper = m.unitePlan.helpers[0].playerId;
      assert.equal(h.ps(firstHelper).pendingFunds, 5, 'first-wave rewards survive the skip');
      h.invariants();
      m.dispose();
    });
  }
}

test('eliminated humans vote; AI, spectators, offline and autoplay seats cannot', () => {
  const h = voteMatch({ humans: 4, bots: 7, beforeCombat: (h) => {
    const ps = h.ps('p_3'); ps.lp = 0; ps.eliminate(1);
    h.m.onDisconnect('p_1');
    h.m.handle('p_2', { t: 'g.autoplay', on: true });
  } });
  const m = h.m;
  assert.deepEqual(m.publicView().unite.skipVote.eligible, ['p_0', 'p_3']);
  assert.equal(m.handle('ai_0', voteMsg).error, ERR.NOT_IN_ROOM);
  assert.equal(m.handle('viewer', voteMsg).error, ERR.SPECTATOR);
  for (const pid of ['p_1', 'p_2']) assert.equal(m.handle(pid, voteMsg).error, ERR.BAD_TARGET);
  assert.deepEqual(m.handle('p_3', voteMsg), { ok: true });
  assert.equal(m.unitePlan.skipRemaining, false);
  m.handle('p_0', voteMsg);
  assert.equal(m.unitePlan.skipRemaining, true);
  m.dispose();
});

test('disconnect, autoplay and leaving discard ineligible votes; reconnecting does not restore a vote', () => {
  const h = voteMatch({ humans: 4, bots: 6 });
  const m = h.m;
  m.handle('p_0', voteMsg);
  m.onDisconnect('p_0');
  assert.deepEqual(m.publicView().unite.skipVote.voters, []);
  m.onReconnect('p_0');
  assert.deepEqual(m.publicView().unite.skipVote.voters, []);
  m.handle('p_0', voteMsg);
  m.handle('p_0', { t: 'g.autoplay', on: true });
  assert.deepEqual(m.publicView().unite.skipVote.voters, []);
  m.handle('p_0', { t: 'g.autoplay', on: false });
  m.handle('p_0', voteMsg);
  m.onLeave('p_0');
  assert.deepEqual(m.publicView().unite.skipVote.voters, []);
  assert.deepEqual(m.publicView().unite.skipVote.eligible, ['p_1', 'p_2', 'p_3']);
  assert.equal(m.publicView().unite.skipVote.needed, 2);
  m.dispose();
});

test('a smaller electorate can approve existing votes; approval stays latched after reconnect', () => {
  const h = voteMatch({ humans: 4 });
  const m = h.m;
  m.handle('p_0', voteMsg); m.handle('p_1', voteMsg);
  assert.equal(m.unitePlan.skipRemaining, false);
  m.onDisconnect('p_2');
  assert.equal(m.unitePlan.skipRemaining, true, 'two of the three eligible humans agree');
  m.onReconnect('p_2');
  assert.equal(m.unitePlan.skipRemaining, true);
  m.dispose();
});

test('insufficient votes keep the second wave and votes never carry into another round', () => {
  const h = voteMatch({ humans: 2 });
  const m = h.m;
  m.handle('p_0', voteMsg);
  h.drive(() => m.phase === PHASE.UNITE && m.unitePlan.round === 2);
  assert.equal(m.publicView().unite.skipVote, null);
  assert.equal(m.handle('p_1', voteMsg).error, ERR.WRONG_PHASE);
  h.toPrep(2);
  assert.equal(m.handle('p_0', voteMsg).error, ERR.WRONG_PHASE);
  h.drive(() => m.phase === PHASE.UNITE && m.unitePlan.round === 1);
  assert.deepEqual(m.publicView().unite.skipVote.voters, []);
  assert.equal(m.unitePlan.skipRemaining, false);
  m.dispose();
});

test('a one-wave plan and a completed first wave reject votes', () => {
  const h = voteMatch({ humans: 3 });
  const m = h.m;
  m.unitePlan.roundsMax = 1;
  assert.equal(m.publicView().unite.skipVote, null);
  assert.equal(m.handle('p_0', voteMsg).error, ERR.WRONG_PHASE);
  m.unitePlan.roundsMax = 2;
  h.drive(() => !m.fields[0].live);
  assert.equal(m.publicView().unite.skipVote.open, false);
  assert.equal(m.handle('p_0', voteMsg).error, ERR.WRONG_PHASE);
  m.dispose();
});

test('zero eligible humans never approve a skip automatically', () => {
  const h = voteMatch({ humans: 1 });
  const m = h.m;
  m.handle('p_0', { t: 'g.autoplay', on: true });
  assert.deepEqual(m.publicView().unite.skipVote.eligible, []);
  assert.equal(m.unitePlan.skipRemaining, false);
  m.handle('p_0', { t: 'g.autoplay', on: false });
  assert.equal(m.publicView().unite.skipVote.needed, 1);
  m.handle('p_0', voteMsg);
  assert.equal(m.unitePlan.skipRemaining, true);
  m.dispose();
});

for (const clientCombat of [false, true]) {
  for (const skipAt of [2, 4]) {
    test(`${clientCombat ? 'client' : 'server'} five-wave plan: fresh ballots can skip all later waves after wave ${skipAt}`, () => {
      const h = voteMatch({ humans: 3, bots: 17, clientCombat });
      const m = h.m;
      try {
        assert.equal(m.unitePlan.roundsMax, 5);
        const oldId = m.publicView().unite.skipVote.id;
        assert.deepEqual(m.handle('p_0', { ...voteMsg, voteId: oldId }), { ok: true });
        assert.equal(m.unitePlan.skipRemaining, false);
        assert.ok(h.drive(() => m.phase === PHASE.UNITE && m.unitePlan.round === skipAt));
        const vote = m.publicView().unite.skipVote;
        assert.notEqual(vote.id, oldId);
        assert.deepEqual(vote.voters, [], 'votes reset rather than accumulating over waves');
        assert.equal(m.handle('p_1', { ...voteMsg, voteId: oldId }).error, ERR.WRONG_PHASE);
        assert.deepEqual(m.publicView().unite.skipVote.voters, [], 'a delayed request cannot vote in a later wave');
        assert.deepEqual(m.handle('p_0', { ...voteMsg, voteId: vote.id }), { ok: true });
        assert.equal(m.unitePlan.skipRemaining, false);
        assert.deepEqual(m.handle('p_1', { ...voteMsg, voteId: vote.id }), { ok: true });
        assert.equal(m.unitePlan.skipRemaining, true);
        assert.equal(m.phase, PHASE.UNITE);
        assert.equal(m.fields[0].live, true, 'approval does not interrupt the current battle');
        assert.ok(h.drive(() => m.phase === PHASE.SETTLE));
        assert.equal(m.unitePlan.round, skipAt);
        assert.equal(new Set(FakeBattle.instances.filter((b) => b.kind === 'unite').map((b) => b.opts.seed)).size, skipAt);
        assert.equal(h.ps('p_0').stats.lpLost, 3);
        const helpers = m.publicView().uniteResult.helpers;
        assert.equal(helpers.length, 2 * skipAt);
        for (const pid of helpers.filter((_, i) => i % 2 === 0)) assert.equal(h.ps(pid).pendingFunds, 5);
        assert.match(h.bc.filter((entry) => entry.t === 'm.ticker').map((entry) => entry.text).join('\n'),
          /本轮结束后跳过后续全部联防/);
        h.invariants();
      } finally { m.dispose(); }
    });
  }
}

test('no eligible reserve helpers means no remaining-wave vote; a later game round has a new vote identity', () => {
  const h = voteMatch({ humans: 3, bots: 17 });
  const m = h.m;
  try {
    const oldId = m.publicView().unite.skipVote.id;
    h.toPrep(2);
    assert.ok(h.drive(() => m.phase === PHASE.UNITE && m.unitePlan.round === 1));
    assert.notEqual(m.publicView().unite.skipVote.id, oldId);
    assert.equal(m.handle('p_0', { ...voteMsg, voteId: oldId }).error, ERR.WRONG_PHASE);
    for (const ps of m.unitePlan.reserveHelpers) ps.left = true;
    assert.equal(m.publicView().unite.skipVote, null);
    assert.equal(m.handle('p_0', voteMsg).error, ERR.WRONG_PHASE);
  } finally { m.dispose(); }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const manager = path.join(root, 'extensions/20p-endless/manage.mjs');
const payload = JSON.parse(fs.readFileSync(path.join(root, 'extensions/20p-endless/payload.json'), 'utf8'));

function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sp-source-extension-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  fs.mkdirSync(path.join(dir, '.git'));
  fs.writeFileSync(path.join(dir, 'package.json'), JSON.stringify({ name: 'stronghold-protocol-alliance', version: '0.3.3' }));
  for (const file of payload.files) if (file.before != null) {
    const full = path.join(dir, file.path);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, file.before);
  }
  return { dir, run: (cmd) => spawnSync(process.execPath, [manager, cmd, '--root', dir], { encoding: 'utf8' }) };
}

test('source extension installs and uninstalls idempotently, retaining unrelated upstream edits', (t) => {
  const { dir, run } = fixture(t);
  const constants = path.join(dir, 'shared/constants.js');
  const extra = '\n// unrelated upstream addition retained by the source extension\n';
  fs.appendFileSync(constants, extra);
  for (const cmd of ['check', 'install', 'install']) {
    const result = run(cmd);
    assert.equal(result.status, 0, result.stderr);
  }
  assert.match(fs.readFileSync(constants, 'utf8'), /MAX_SEATS = 20/);
  assert.ok(fs.readFileSync(constants, 'utf8').endsWith(extra));
  for (const cmd of ['uninstall', 'uninstall']) {
    const result = run(cmd);
    assert.equal(result.status, 0, result.stderr);
  }
  for (const file of payload.files) {
    const full = path.join(dir, file.path);
    if (file.before == null) assert.equal(fs.existsSync(full), false, file.path);
    else assert.equal(fs.readFileSync(full, 'utf8'), file.before + (file.path === 'shared/constants.js' ? extra : ''), file.path);
  }
});

test('source extension refuses every write when one upstream file conflicts', (t) => {
  const { dir, run } = fixture(t);
  const constants = path.join(dir, 'shared/constants.js');
  fs.writeFileSync(constants, fs.readFileSync(constants, 'utf8').replace('export const MAX_SEATS = 4;', 'export const MAX_SEATS = 12;'));
  const before = payload.files.map((f) => [f.path, fs.existsSync(path.join(dir, f.path)) ? fs.readFileSync(path.join(dir, f.path), 'utf8') : null]);
  const result = run('install');
  assert.equal(result.status, 1);
  assert.match(result.stderr, /shared\/constants.js/);
  for (const [rel, text] of before) {
    const full = path.join(dir, rel);
    assert.equal(fs.existsSync(full) ? fs.readFileSync(full, 'utf8') : null, text, rel);
  }
});

