test('test results never persist and legacy test records stay excluded from every tally', () => {
  const content = { cs: 'ab'.repeat(32), vanilla: false, plugins: [{ id: 'x', version: '1' }] };
  const real = buildRecord(baseResult(), { myId: 'p1', now: 1 });
