}));
const poolGroups = [{ id: 1, playerIds: ['a1', 'a2', 'a3'] }, { id: 2, playerIds: ['b1', 'b2', 'b3'] }];
const cards = () => Array.from({ length: 6 }, (_, idx) => ({ name: `选项${idx}`, desc: '效果' }));
