    const sp = normalizeSp(frame, players, 'p5', fixedGroups);
    assert.equal(sp.groups.length, 2);
    assert.equal(sp.cards[0].id, 'b0');
    assert.deepEqual(sp.groups[1].playerIds, members(2));
  });
});

