test('#484: enemy information uses this match\'s announced leader, abilities, battlefield and special enemy types', () => {
  const h = makeMatch({ mode: 'coop', difficulty: 'HARD', humans: 1, seed: 4 }).start();
  try {
    const pub = h.m.publicView();
